"""Compile a draft scientific report and figures exclusively from saved evidence.

No network calls, synthetic observations, or undocumented metric defaults. Missing
optional evidence is disclosed; required input failures stop report generation.
"""
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import argparse,hashlib,json,math
from datetime import datetime,timezone
from backend.paths import ROOT,write_json

REQUIRED=('api_status.json','model_evaluation.json','demo_results.json')
OPTIONAL=('model_timing.json','noaa_coverage.json','route_lab_osrm.json','validation.json','evidence_ingestion.json','operations_demo.json','usda_food_environment.json','ingestion_verification.json','clean_install.json')
NAMES={'A':'Baseline distribution','B':'Targeted verification','C':'Precautionary hold pending review','D':'Alternative eligible supply'}

def load_evidence(reports_dir,inventory_path):
    data={};paths={'inventory':inventory_path}
    for name in REQUIRED:
        paths[name.removesuffix('.json')]=reports_dir/name
    for name in OPTIONAL:
        p=reports_dir/name
        if p.exists():paths[name.removesuffix('.json')]=p
    for key,path in paths.items():
        if not path.is_file():raise FileNotFoundError(f'Required report evidence not found: {path}')
        data[key]=json.loads(path.read_text(encoding='utf-8'))
    manifest=[{'input':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in paths.values()]
    return data,manifest

def number(value,digits=4):
    if value is None:return 'not available'
    if isinstance(value,float) and not math.isfinite(value):return 'not available'
    return f'{value:,.{digits}f}' if digits else f'{value:,}'

def metric_row(name,metric):
    interval=metric.get('brier_week_block_bootstrap_95_ci')
    ci=' to '.join(number(v,6) for v in interval) if interval else 'not available'
    return f"| {name} | {number(metric.get('n'),0)} | {number(metric.get('brier'),8)} | {ci} | {number(metric.get('pr_auc_average_precision'),6)} | {number(metric.get('roc_auc'),6)} |"

def scenario_table(plans):
    lines=['| Scenario | Solver | Logistics cost (simulated $) | Unmet demand (kg) | Candidates not selected | Review-priority selections | Violations |','|---|---|---:|---:|---:|---:|---:|']
    for p in plans:
        lines.append(f"| {p['scenario']} - {NAMES.get(p['scenario'],p['scenario'])} | {p['solver_status']} | {number(p['total_logistics_cost'],0)} | {number(p['unmet_demand_kg'],0)} | {p['affected_shipments']} | {p['review_priority_count']} | {p['constraint_violations']} |")
    return '\n'.join(lines)

