def build_text(data,figures=True):
    inventory=data['inventory'];files=inventory['files'];api=data['api_status'];model=data['model_evaluation'];demo=data['demo_results'];timing=data.get('model_timing');weather=data.get('noaa_coverage');routing=data.get('route_lab_osrm');validation=data.get('validation')
    errors=sum(bool(f.get('errors')) for f in files);duplicates=sum(bool(f.get('duplicate_of')) for f in files);http_success=sum(bool(r.get('success')) for r in api)
    lines=['# AEGIS: Adaptive Early-warning & Guidance for Integrated Supply Chains','', '**Draft scientific competition report — genuine Kiro application usage, author signoff, and official-rubric review pending.**','', 'Report compiled from saved artifacts on '+datetime.now(timezone.utc).date().isoformat()+'. This document describes a local research prototype; it does not establish regulatory authority, operational certification, or prospective model validity.','', '## Abstract','',f'AEGIS combines separately labeled food-safety evidence, public weather and road information, deterministic fictional Missouri logistics, and human-reviewed decision support. The saved raw-data audit inventories {len(files):,} files, with {errors} recorded read errors and {duplicates} exact duplicate hashes. A national FSIS primary-sample study evaluates Salmonella positivity using chronological validation; the transparent historical estimator remains operationally selected. Four constrained allocation responses expose service/cost tradeoffs, and a separate route laboratory supports one farm or multiple dispatch origins. Decisions remain proposed until dispatcher approval; the driver mode exposes approved assignments, advisories, cargo status, and incident reporting.','', '## 1. Operational question and scope','', 'The initial actor is a regional poultry distributor serving Columbia, Kansas City, Jefferson City, Springfield, and St. Louis, Missouri. The route laboratory also represents a single farm dispatching several trucks and a fleet starting from multiple depots. Suppliers, commercial relationships, customer locations, trucks, lots, shipments, inventory, demand, costs, cargo telemetry, and thermal assumptions are simulated. Official facility markers and road geometry provide geographic context without validating fictional supply contracts.','', 'The P0 submission scope is source integration/provenance, scientifically qualified model/baseline validation, at least three response scenarios, the requested genuine Kiro workflow, and report/code/demo artifacts. The interactive twin and optimization support that scope. An LLM assistant, account systems, and live sensors remain future extensions.','', '## 2. Data and provenance','',f"The audit ran against `{inventory.get('data_dir','recorded source directory')}`. CSV and nested JSON are parsed without concatenating unrelated source tables; checksums detect exact duplicate downloads. JSON primary/secondary counts are preserved. Spreadsheet sheet dimensions are explicitly declared rather than exact observation counts. Errors, timestamps, sample missingness, and schemas appear in `data/manifests/inventory.json` and `reports/data_audit.md`.",'', '| Evidence | Role | Scientific boundary |','|---|---|---|','| FSIS raw-poultry primary tests | National selected-sampling target and history | Primary Positive/Negative results only; secondary typing is not another primary sample |','| FSIS RTE example, other commodities, NARMS | Audited supporting files | Not silently pooled into a poultry training set |','| CDC BEAM exports | Human surveillance context | Separate denominators; no causal sample/outbreak linkage claimed |','| CDC NORS | Historical outbreak context | Separate from FSIS selected-sampling outcomes |','| FSIS official recalls | Dated official notices | No verified match to fictional lot identifiers |','| NOAA/NCEI daily summaries | Observed historical ambient weather | Reporting-period dates, attributes, quality flags, retrieval times kept separate |','| Open-Meteo forecast and archive | Forecast and historical reanalysis, respectively | Neither replaces observed station weather |','| NWS warnings | Official severe-weather advisories | Absence applies to the saved request/time only |','| MoDOT events and OSRM | Road evidence and ordinary driving estimates | Proximity screening is not closure-aware, truck-certified navigation |','| USDA food-access/environment workbooks | Audited food-security context | Not yet weighted into allocation without vintage/geography/denominator validation |','',f'The saved connectivity probe recorded {http_success}/{len(api)} HTTP successes. Documentation/catalog reachability is distinguished from working data feeds. Exact URLs, response types, request times, latencies, and failures are in `reports/api_status.json` and the API registry. These results describe the recorded probes, not guaranteed present availability.']
    failures=[r for r in api if not r.get('success')]
    if failures:lines+=['','Recorded probe failures:']+[f"- {r['id']}: {r.get('failure','failure reason unavailable')}" for r in failures]
    if weather:
        lines+=['','### 2.1 Bounded NOAA coverage','',f"The actual NCEI extract covers {weather['start_date']} through {weather['end_date']}: {weather['station_count']} verified station locations and {weather['observed_station_days']:,}/{weather['expected_station_days']:,} requested station-date rows. Overall status is **{weather['status']}** because date coverage and variable completeness are separate. There are {weather['missing_metric_values']} missing requested variable values; no values were filled.",'','| Missouri location | Verified station | Latitude, longitude | Date rows / expected | Missing TMAX | Missing TMIN | Missing PRCP |','|---|---|---|---:|---:|---:|---:|']
        for s in weather['stations']:
            if s.get('error'):lines.append(f"| {s['city']} | {s['station_id']} | unverified | failed | unknown | unknown | {s['error']} |");continue
            m=s['metric_coverage'];lines.append(f"| {s['city']} | {s['station_id']} | {s['latitude']}, {s['longitude']} | {s['observed_days']}/{s['expected_days']} | {m['TMAX']['missing_days']} | {m['TMIN']['missing_days']} | {m['PRCP']['missing_days']} |")
        lines+=['','NCEI requests explicitly specify metric units. Original bytes, station identities, coordinates, attributes, retrieval timestamps, and SHA-256 records are retained in `data/external/noaa/`. Blank quality flags indicate no recorded failed quality check; they do not imply error-free measurements. Daily reporting labels are not converted silently to UTC or local midnight. These observations have **not** been joined to FSIS: national establishment coverage, exposure linkage, and actual feature-publication times remain unvalidated.']
        if figures:lines+=['','![NOAA variable completeness by station](figures/noaa_variable_coverage.png)','', '*Figure 1. Numeric variable completeness within the requested station/date window. Cell annotations include missing-value counts. Full date-row coverage does not imply complete precipitation coverage.*']
    else:lines+=['','NOAA expanded-coverage evidence is missing from the supplied report artifacts; no coverage result is inferred.']
    lines+=['','## 3. Sampling-outcome feasibility study','', 'The modeled quantity is positivity in a selected FSIS raw-poultry primary Salmonella sample. It is not the probability of consumer illness, nor a farm-, shipment-, or lot-specific contamination probability. The ingestion adapter verifies embedded product metadata, retains establishment/project/date identifiers, excludes secondary typing from the target, and rejects conflicting duplicate sample identifiers.','',f"The original feasibility evaluation uses {model['training_rows']:,} training and {model['validation_rows']:,} validation rows, with a {model['embargo_days']}-day embargo. Its held-out dates are {model['validation_start'][:10]} through {model['validation_end'][:10]}. Features are lagged national historical prevalence and calendar seasonality. The assumed 90-day reporting lag is not an empirically verified publication date.",'','| Estimator: original retrospective cohort | Validation samples | Brier | 95% week-block bootstrap interval | PR-AUC (AP) | ROC-AUC |','|---|---:|---:|---|---:|---:|',metric_row('Smoothed historical prevalence',model['baseline']),metric_row('Logistic regression diagnostic',model['logistic_regression']),'','Lower Brier is better. The original logistic model does not improve upon the baseline in this held-out cohort. Calibration, precision/recall at the documented threshold, and state-level error analysis are retained in `reports/model_evaluation.json`. There are no invented accuracy percentages.']
    if timing:
        split=timing['strict_split'];lines+=['','### 3.1 Availability sensitivity analysis','',f"A separate frozen-source analysis uses only earlier source snapshots created on or before {split['training_snapshot_cutoff']}. It fits {split['training_rows']:,} eligible FY2024/FY2025 rows and evaluates {split['validation_rows']:,} FY2026 samples dated {split['validation_start']} through {split['validation_end']}. No held-out outcomes update either estimator. The later FY2026 file is used only to score frozen predictions.",'','| Estimator: frozen earlier-snapshot cohort | Validation samples | Brier | 95% week-block bootstrap interval | PR-AUC (AP) | ROC-AUC |','|---|---:|---:|---|---:|---:|',metric_row('Frozen smoothed historical prevalence',timing['snapshot_baseline']),metric_row('Calendar-only logistic diagnostic',timing['calendar_logistic']),'','Metadata creation dates are **not verified public release dates**. Row-level result availability and historical as-of revisions remain unknown. The small numerical difference in this sensitivity study does not justify replacing the transparent historical estimator. Prospective validation remains unestablished. The two reported cohorts differ; their absolute losses should not be interpreted as a before/after model improvement.']
    else:lines+=['','The earlier-snapshot timing analysis is absent; no release-aware result is inferred.']
    if figures:lines+=['','![Measured model Brier scores and uncertainty](figures/model_brier_intervals.png)','', '*Figure 2. Measured Brier scores with weekly-block bootstrap intervals. Panels use different held-out samples. Intervals summarize held-out weekly variation and do not quantify selection or publication-lag uncertainty.*']
    lines+=['','## 4. Simulated digital twin and four response scenarios','',f"The saved demo uses seed `{demo['seed']}`. The core network contains three simulated suppliers, two DCs, fifteen destinations, eight refrigerated trucks, twelve lots, and twenty-four candidate shipments. The single-wave allocation maximizes served demand less simulated logistics cost under hard inventory, supplier/DC capacity, truck eligibility/refrigeration/capacity, lot hold/recall, destination demand, deadline, and shelf-life constraints. It does not represent a full replenishment system or physical dispatch.",'', 'A retains original candidate lots. B adds targeted verification requirements and cost. C proposes precautionary holds for dispatcher review. D permits eligible simulated supply substitution. Predictive scores alone do not create mandatory holds. Held or recalled lots cannot be assigned regardless of objective weights.','', '### 4.1 Baseline seed results','',scenario_table(demo['baseline']),'', '### 4.2 Results after scripted operational events','',scenario_table(demo['after_events']),'', 'The scripted narrative introduces simulated road delay and cargo temperature excursion. Lower logistics cost after disruptions can result from serving fewer shipments; it is not necessarily a better response. The tradeoff must be interpreted alongside unmet demand and review requirements. Food waste is not equated with unsent stock; the six-hour wave does not generate expiry in the current assumptions.']
    if figures:lines+=['','![Scenario logistics cost and unmet demand](figures/scenario_tradeoffs.png)','', '*Figure 3. Four response scenarios before and after the scripted events. Costs are simulated dollars. Demand/cost differences are synthetic decision-support results, not measured commercial savings.*']
    lines+=['','## 5. Single-farm and multi-origin route laboratory','', 'The route laboratory is a separate what-if tool sharing the same backend and map. It supports multiple trucks, stop demands, loading inventory, eligibility, service time, deadlines, and return to each truck\'s origin. It does not create accounts or alter approved driver assignments. A deterministic thermal scenario projects temperature under declared ambient/fault assumptions; it is uncalibrated and produces no learned refrigeration-failure probability.']
    if routing:
        lines+=['','| Preset | Origins / available trucks / stops | Solver | Matrix fallback | Planned routes | Fleet distance (km) | Total vehicle-hours | Cost (simulated $) | Unmet demand (kg) | Violations |','|---|---|---|---|---:|---:|---:|---:|---:|---:|']
        for r in routing:
            p=r['preset'];s=r['summary'];lines.append(f"| {p['name']} | {len(p['origins'])} / {len(p['trucks'])} / {len(p['stops'])} | {r['solver_status']} | {r['matrix_fallback']} | {len(r['routes'])} | {number(s['total_distance_m']/1000,3)} | {number(s['total_duration_seconds']/3600,3)} | {number(s['total_cost'],2)} | {s['unmet_demand_kg']} | {s['constraint_violations']} |")
        all_live=all(not r.get('matrix_fallback',True) and all(not route.get('fallback',True) for route in r['routes']) for r in routing)
        route_source='actual low-volume OSRM requests' if all_live else 'a mixture of OSRM responses and explicitly labeled estimated fallbacks'
        all_unserved_held=all(set(r['summary']['unserved_stops'])<={s['id'] for s in r['preset']['stops'] if s.get('held')} for r in routing)
        hold_note='The designated held stop remains unserved in each saved preset; its demand is not silently discarded.' if all_unserved_held else 'Unserved stops and demand remain in each reported result; check eligibility and routing constraints before interpreting a nonselection.'
        lines+=['',f'These rows come from {route_source} and saved OR-Tools results in `reports/route_lab_osrm.json`. A FEASIBLE status is not a global-optimality proof. Vehicle-hours sum all planned vehicle elapsed times and may exceed one vehicle\'s shift limit. {hold_note}','', 'Real road incidents are screened against returned route geometry with a 250-meter proximity/intersection buffer. Nearby parallel roads and duplicate point/line event representations can generate review alerts. Public OSRM driving routes do not incorporate current MoDOT closures automatically and do not validate truck height, weight, hazardous-material restrictions, or legal access. Every alternative requires dispatcher and commercial-vehicle review; none is asserted truck-safe.']
    else:lines+=['','Saved live route-laboratory results were not supplied; routing performance is therefore not quantified.']
    lines+=['','## 6. Human approval and AEGIS Drive','', 'Command and Drive are responsive modes in one application with a shared FastAPI/SQLite backend. Drive provides approved shipment information, disruption advisories, cargo-temperature status, and incident reporting. It is intended for use while parked. Dispatcher approval requires an identity and reason, rejects stale network revisions, revalidates safety constraints, publishes assignments transactionally, and retains an audit trail. Local identities remain self-declared; production access control is outside this prototype.','',f"The accelerated isolated workflow recorded {demo['approved_assignments']} approved simulated assignments. Acknowledgment recorded: {demo['acknowledgment_recorded']}; incident recorded: {demo['incident_recorded']}; operator database modified by that rehearsal: {demo['production_database_modified']}. This validates the scripted sequence without claiming a completed five-minute live presentation.",'', '## 7. Reproducibility and verification','', 'Required inputs, retrieval records, seeds, commands, and test artifacts remain inspectable. This report compiler performs no new HTTP requests. Its input-file hashes are recorded in `reports/figures/input_manifest.json`; regenerating after evidence changes updates the draft transparently.']
    if validation:lines+=['',f"The saved validation artifact records {validation.get('pytest_passed','not recorded')} passing pytest tests, {validation.get('vitest_passed','not recorded')} passing Vitest tests, frontend build status `{validation.get('frontend_production_build','not recorded')}`, and {validation.get('real_http_checks_passed','not recorded')} real HTTP checks. Browser visual QA: `{validation.get('browser_visual_qa','not recorded')}`. These are the artifact's recorded results; final session verification and author signoff must be refreshed before submission."]
    lines+=['','```powershell','.venv/Scripts/python scripts/audit_data.py','.venv/Scripts/python scripts/ingest_fsis.py','.venv/Scripts/python scripts/ingest_evidence.py','.venv/Scripts/python scripts/train_model.py','.venv/Scripts/python scripts/acquire_noaa.py','.venv/Scripts/python scripts/validate_model_timing.py','.venv/Scripts/python scripts/demo_run.py','.venv/Scripts/python scripts/build_submission_report.py','.venv/Scripts/python -m pytest -q','```','', 'Frontend build/test and local startup commands are in `README.md`. Source refresh and route-laboratory runs require internet; dated evidence and labeled estimates support a limited offline demonstration.','', '## 8. Limitations and submission readiness','', '- No validated prospective contamination or consumer-illness prediction is claimed. Source selection, missing publication dates, retrospective revisions, and transportability constrain interpretation.','- NOAA coverage is a bounded five-station extract. Weather is not scientifically linked to national FSIS outcomes, farm production, or cargo safety.','- Thermal projections are scenario calculations with declared assumptions; live sensors and calibrated cargo models are absent.','- Allocation and route-laboratory outputs describe different synthetic decision problems. Neither establishes commercial savings or complete upstream replenishment.','- Verified recall matching requires genuine establishment/product/lot/date traceability, which fictional lots cannot supply.','- Truck-safe routing, production authorization, live sensing, farm/enterprise account systems, and an LLM operations assistant remain outside the validated submission core.','- Genuine AWS Kiro application use remains pending. Codex-prepared `.kiro/` files do not demonstrate using Kiro.','- Official challenge rubric, submission rules, required Kiro evidence, final author review, and the timed presentation must be confirmed before this draft becomes a final submission.','', '## References and primary-source documentation','', '1. USDA FSIS. [Laboratory Sampling Data](https://www.fsis.usda.gov/science-data/data-sets-visualizations/laboratory-sampling-data). Embedded metadata in the supplied FY2024–FY2026 raw-poultry files defines primary/secondary tests and warns against inferring outbreak causality.','2. USDA FSIS. [Official recall API](https://www.fsis.usda.gov/fsis/api/recall/v/1). Dated response artifacts retain source and retrieval timestamps.','3. NOAA NCEI. [Access Data Service API documentation](https://www.ncei.noaa.gov/support/access-data-service-api-user-documentation). Explicit dataset, station, date, units, attributes, and station-location parameters.','4. NOAA NCEI. [GHCN-Daily format and quality flags](https://www.ncei.noaa.gov/pub/data/ghcn/daily/readme.txt).','5. CDC. [NORS data](https://www.cdc.gov/nors/data/) and [BEAM dashboard](https://www.cdc.gov/beam/dashboard/).','6. MoDOT. [Traveler Information ArcGIS service](https://mapping.modot.mo.gov/arcgis/rest/services/TravelerInformation/TravelerInformationData/MapServer).','7. Project OSRM. [HTTP API](https://project-osrm.org/docs/v26.6.1/http/).','8. NAFSI Hub. [Public challenge announcement](https://nafsihub.org/). Public announcement review does not replace the full official rubric.','']
    return '\n'.join(lines)+operations_appendix(data)

def generate_figures(data,folder):
    import os
    os.environ.setdefault('MPLCONFIGDIR',str(ROOT/'data/cache/matplotlib'))
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import numpy as np
    folder.mkdir(parents=True,exist_ok=True)
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.dpi':140,'savefig.dpi':240,'svg.hashsalt':'aegis-submission-v1'})
    def save(fig,name):
        for ext in ('png','svg','pdf'):
            metadata={'Creator':'AEGIS reproducible report compiler'}
            if ext=='pdf':metadata.update(CreationDate=None,ModDate=None)
            fig.savefig(folder/f'{name}.{ext}',bbox_inches='tight',metadata=metadata)
        plt.close(fig)
    model=data['model_evaluation'];cohorts=[('Original retrospective holdout',model['baseline'],model['logistic_regression'])]
    if data.get('model_timing'):
        timing=data['model_timing'];cohorts.append(('Earlier-snapshot sensitivity cohort',timing['snapshot_baseline'],timing['calendar_logistic']))
    fig,axes=plt.subplots(1,len(cohorts),figsize=(6.2*len(cohorts),3.4),squeeze=False)
    for ax,(title,baseline,fitted) in zip(axes[0],cohorts):
        for index,(label,metric,color) in enumerate([('Historical prevalence',baseline,'#245e50'),('Logistic diagnostic',fitted,'#bb7c2f')]):
            value=metric['brier'];lo,hi=metric['brier_week_block_bootstrap_95_ci'];ax.errorbar(value,index,xerr=[[value-lo],[hi-value]],fmt='o',capsize=5,color=color,label=label);ax.annotate(f'{value:.6f}',(value,index),xytext=(0,12),textcoords='offset points',ha='center',fontsize=9)
        ax.set(yticks=[0,1],yticklabels=['Historical prevalence','Logistic diagnostic'],ylim=(-.5,1.55),xlabel='Brier score (lower is better)',title=f"{title}\nn={baseline['n']:,}");ax.grid(axis='x',alpha=.2)
    fig.suptitle('Selected-sample Salmonella positivity: measured loss and weekly-block intervals',fontsize=12,y=1.06);fig.tight_layout();save(fig,'model_brier_intervals')
    demo=data['demo_results'];before={p['scenario']:p for p in demo['baseline']};after={p['scenario']:p for p in demo['after_events']};letters=list(before);x=np.arange(len(letters));fig,axes=plt.subplots(1,2,figsize=(11,3.7))
    for ax,key,label in zip(axes,['total_logistics_cost','unmet_demand_kg'],['Logistics cost (simulated $)','Unmet demand (kg)']):
        for shift,plans,color,name in [(-.18,before,'#245e50','Before scripted events'),(.18,after,'#c28b48','After scripted events')]:
            vals=[plans[k][key] for k in letters];bars=ax.bar(x+shift,vals,.36,color=color,label=name);ax.bar_label(bars,labels=[f'{v:,}' for v in vals],padding=3,fontsize=8)
        ax.set(xticks=x,xticklabels=letters,xlabel='Response scenario',ylabel=label,ylim=(0,max(max(before[k][key],after[k][key]) for k in letters)*1.2));ax.grid(axis='y',alpha=.15)
    axes[0].legend(frameon=False,fontsize=9);fig.suptitle('Deterministic operational responses: service and cost must be read together',fontsize=12);fig.tight_layout();save(fig,'scenario_tradeoffs')
    weather=data.get('noaa_coverage')
    if weather:
        stations=[s for s in weather['stations'] if not s.get('error')];values=np.array([[s['metric_coverage'][m]['numeric_days']/s['expected_days']*100 for m in ['TMAX','TMIN','PRCP']] for s in stations]);fig,ax=plt.subplots(figsize=(7.2,4.0));im=ax.imshow(values,cmap='YlGn',vmin=min(98,float(values.min())),vmax=100,aspect='auto')
        for i,s in enumerate(stations):
            for j,m in enumerate(['TMAX','TMIN','PRCP']):ax.text(j,i,f"{values[i,j]:.2f}%\n({s['metric_coverage'][m]['missing_days']} missing)",ha='center',va='center',fontsize=9,color='white' if values[i,j]>99 else '#183b30')
        ax.set(xticks=[0,1,2],xticklabels=['TMAX (°C)','TMIN (°C)','PRCP (mm)'],yticks=range(len(stations)),yticklabels=[s['city'] for s in stations],title=f"NOAA variable completeness\n{weather['start_date']} through {weather['end_date']}");fig.colorbar(im,ax=ax,label='Available numeric observations (%)');fig.tight_layout();save(fig,'noaa_variable_coverage')

def main():
    p=argparse.ArgumentParser();p.add_argument('--reports-dir',type=Path,default=ROOT/'reports');p.add_argument('--inventory',type=Path,default=ROOT/'data/manifests/inventory.json');p.add_argument('--output',type=Path);p.add_argument('--no-figures',action='store_true');args=p.parse_args()
    data,manifest=load_evidence(args.reports_dir,args.inventory);folder=args.reports_dir/'figures'
    if not args.no_figures:generate_figures(data,folder)
    output=args.output or args.reports_dir/'aegis_report.md';output.parent.mkdir(parents=True,exist_ok=True);output.write_text(build_text(data,not args.no_figures),encoding='utf-8');write_json(folder/'input_manifest.json',{'generated_at':datetime.now(timezone.utc).isoformat(),'inputs':manifest,'draft':True});print('Wrote',output)
if __name__=='__main__':main()
